"""Generate regexp-fuzzer inputs for ClusterFuzz.

Blackbox-fuzzer contract:

  run.py --input_dir <corpus> --output_dir <dir> --no_of_files <n>

For each fuzz-N.js, also writes flags-N.js with the v8_foozzie.py flags for
that testcase: random seed, first and second config, second d8 and extra
flags. These are drawn from v8_fuzz_experiments_regexp.json and
v8_fuzz_flags_regexp.json, read
from the V8 build directory ($APP_DIR on ClusterFuzz; the foozzie source
directory otherwise).

Each output file is self-contained and records its seed and grammar profile.
The input corpus is unused.
"""

import argparse
import json
import os
import random
import sys

from pathlib import Path

import grammar
import harness

# 500 cases amortize d8 startup while keeping normal simulator runs below
# foozzie's 3s timeout.
DEFAULT_CASES_PER_FILE = 500

EXPERIMENTS_FILE = "v8_fuzz_experiments_regexp.json"
ADDITIONAL_FLAGS_FILE = "v8_fuzz_flags_regexp.json"

# Where the foozzie tables live in a V8 checkout. Resolved from this file's
# location (tools/regexp/correctness_fuzzer/run.py), not the working
# directory, so local runs need no APP_DIR. Absent in the ClusterFuzz bundle.
TOOLS_DIR = Path(__file__).resolve().parent.parent.parent
FOOZZIE_SOURCE_DIR = TOOLS_DIR / "clusterfuzz" / "foozzie"


def build_dir():
  """Directory holding the foozzie tables bundled with d8.

  ClusterFuzz sets APP_DIR to the build directory, as js_fuzzer expects. Local
  runs from a checkout fall back to the tables' source directory.
  """
  if "APP_DIR" in os.environ:
    return Path(os.environ["APP_DIR"])
  if (FOOZZIE_SOURCE_DIR / EXPERIMENTS_FILE).is_file():
    return FOOZZIE_SOURCE_DIR
  sys.exit("run.py: set APP_DIR to the d8 build directory (not running from "
           "a V8 checkout, so there is no fallback)")


def load_json_from_build(name):
  """Load a foozzie config table bundled with d8."""
  with (build_dir() / name).open(encoding="utf-8") as f:
    return json.load(f)


def choose_foozzie_flags(rng, experiments, additional_flags, random_seed):
  """Randomly choose v8_foozzie.py flags from the experiment tables.

  Same distribution as v8_fuzz_config.Config.choose_foozzie_flags and
  js_fuzzer's chooseRandomFlags.
  """
  # Pick one experiment row, weighted by its probability column.
  weights = [row[0] for row in experiments]
  _, first_config, second_config, second_d8 = rng.choices(
      experiments, weights=weights)[0]
  flags = [
      "--random-seed=" + str(random_seed),
      "--first-config=" + first_config,
      "--second-config=" + second_config,
      "--second-d8=" + second_d8,
  ]

  # Add additional flags to second config based on experiment percentages.
  for p, extra in additional_flags:
    if rng.random() < p:
      flags += ["--second-config-extra-flags=" + f for f in extra.split()]
  return flags


def generate_file(seed, profile, max_depth, cases_per_file):
  """Generate a deterministic testcase."""
  rng = random.Random(seed)
  weights = grammar.parse_weights(profile, None)
  cases = [
      grammar.gen_case(rng, max_depth, weights) for _ in range(cases_per_file)
  ]
  header = [
      "Generated by tools/regexp/correctness_fuzzer/run.py",
      "seed=%d profile=%s max_depth=%d" % (seed, profile, max_depth),
      "Replay: correctness_fuzzer.py --ref <d8> --test <d8:--flags> "
      "--testcase <this file>",
  ]
  return harness.emit_js(cases, header)


def main(argv=None):
  ap = argparse.ArgumentParser(
      description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
  ap.add_argument("--input_dir", help="corpus directory; accepted and unused")
  ap.add_argument("--output_dir", required=True)
  ap.add_argument("--no_of_files", type=int, required=True)
  ap.add_argument(
      "--cases-per-file",
      type=int,
      default=DEFAULT_CASES_PER_FILE,
      help="cases per generated file (default %(default)s)")
  ap.add_argument(
      "--max-depth",
      type=int,
      default=5,
      help="derivation depth budget, as in correctness_fuzzer.py")
  args = ap.parse_args(argv)

  experiments = load_json_from_build(EXPERIMENTS_FILE)
  additional_flags = load_json_from_build(ADDITIONAL_FLAGS_FILE)

  os.makedirs(args.output_dir, exist_ok=True)
  # Draw independent seeds for concurrent generator instances.
  sysrand = random.SystemRandom()
  # Profiles change rule weights without changing reachability.
  profiles = sorted(grammar.PROFILES)
  for i in range(args.no_of_files):
    seed = sysrand.randrange(2**32)
    random_seed = sysrand.randrange(1, 2**31)
    profile = profiles[sysrand.randrange(len(profiles))]
    text = generate_file(seed, profile, args.max_depth, args.cases_per_file)
    path = os.path.join(args.output_dir, "fuzz-%d.js" % i)
    with open(path, "w", encoding="utf-8") as f:
      f.write(text)
    flags = choose_foozzie_flags(sysrand, experiments, additional_flags,
                                 random_seed)
    path = os.path.join(args.output_dir, "flags-%d.js" % i)
    with open(path, "w", encoding="utf-8") as f:
      f.write(" ".join(flags))
  return 0


if __name__ == "__main__":
  sys.exit(main())
